 "content": "from collections import Counter


def transform(grid):
    """Mark each compartment containing multiple non-background objects."""
    h, w = len(grid), len(grid[0])
    uniform_lines = []
    for r, row in enumerate(grid):
        if len(set(row)) == 1:
            uniform_lines.append((row[0], "row", r))
    for c in range(w):
        vals = [grid[r][c] for r in range(h)]
        if len(set(vals)) == 1:
            uniform_lines.append((vals[0], "col", c))

    # The grid's full-length solid lines are the compartment dividers.
    divider_color = Counter(color for color, _, _ in uniform_lines).most_common(1)[0][0]
    div_rows = sorted(i for color, axis, i in uniform_lines if color == divider_color and axis == "row")
    div_cols = sorted(i for color, axis, i in uniform_lines if color == divider_color and axis == "col")
    row_ranges = []
    start = 0
    for r in div_rows:
        if start < r:
            row_ranges.append((start, r))
        start = r + 1
    if start < h:
        row_ranges.append((start, h))
    col_ranges = []
    start = 0
    for c in div_cols:
        if start < c:
            col_ranges.append((start, c))
        start = c + 1
    if start < w:
        col_ranges.append((start, w))

    divider_cells = set(div_rows)
    divider_col_cells = set(div_cols)
    counts = Counter(
        grid[r][c]
        for r in range(h) if r not in divider_cells
        for c in range(w) if c not in divider_col_cells
    )
    background = counts.most_common(1)[0][0]

    result = []
    for r0, r1 in row_ranges:
        out_row = []
        for c0, c1 in col_ranges:
            objects = sum(
                grid[r][c] != background and grid[r][c] != divider_color
                for r in range(r0, r1) for c in range(c0, c1)
            )
            out_row.append(1 if objects > 1 else background)
        result.append(out_row)
    return result
